	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&tax_jurisdiction_codeNull,
		&tax_group_codeNull,
		&tax_typeInt,
		&maximum_amount_qtyNull,
		&tax_below_maximumNull,
		&tax_above_maximumNull,
		&effective_dateNull,
		&calculate_tax_on_taxBool,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Tax_Detail: %v\n", err)
		return false
	}

