// Insert inserts the record into the database
func (t *TaxDetail) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, TaxDetailTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Tax_jurisdiction_code,
		t.Tax_group_code,
		t.Tax_type,
		t.Maximum_amount_qty,
		t.Tax_below_maximum,
		t.Tax_above_maximum,
		types.KeyDate(t.Effective_date),
		t.Calculate_tax_on_tax,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (tax_jurisdiction_code, tax_group_code, tax_type, maximum_amount_qty, tax_below_maximum, tax_above_maximum, effective_date, calculate_tax_on_tax) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (tax_jurisdiction_code, tax_group_code, tax_type, effective_date) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Tax_Detail: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(TaxDetailTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *TaxDetail) InsertAll(records []*TaxDetail, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Tax_jurisdiction_code,
			r.Tax_group_code,
			r.Tax_type,
			r.Maximum_amount_qty,
			r.Tax_below_maximum,
			r.Tax_above_maximum,
			types.KeyDate(r.Effective_date),
			r.Calculate_tax_on_tax,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, TaxDetailTableName)
	columns := []string{"tax_jurisdiction_code", "tax_group_code", "tax_type", "maximum_amount_qty", "tax_below_maximum", "tax_above_maximum", "effective_date", "calculate_tax_on_tax"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *TaxDetail) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("tax_jurisdiction_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("tax_group_code") {
			keyChanged = true
		}
		if t.hasFieldChanged("tax_type") {
			keyChanged = true
		}
		if t.hasFieldChanged("effective_date") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, TaxDetailTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("tax_jurisdiction_code") {
			setClauses = append(setClauses, "tax_jurisdiction_code = ?")
			values = append(values, t.Tax_jurisdiction_code)
		}
		if t.hasFieldChanged("tax_group_code") {
			setClauses = append(setClauses, "tax_group_code = ?")
			values = append(values, t.Tax_group_code)
		}
		if t.hasFieldChanged("tax_type") {
			setClauses = append(setClauses, "tax_type = ?")
			values = append(values, t.Tax_type)
		}
		if t.hasFieldChanged("maximum_amount_qty") {
			setClauses = append(setClauses, "maximum_amount_qty = ?")
			values = append(values, t.Maximum_amount_qty)
		}
		if t.hasFieldChanged("tax_below_maximum") {
			setClauses = append(setClauses, "tax_below_maximum = ?")
			values = append(values, t.Tax_below_maximum)
		}
		if t.hasFieldChanged("tax_above_maximum") {
			setClauses = append(setClauses, "tax_above_maximum = ?")
			values = append(values, t.Tax_above_maximum)
		}
		if t.hasFieldChanged("effective_date") {
			setClauses = append(setClauses, "effective_date = ?")
			values = append(values, types.KeyDate(t.Effective_date))
		}
		if t.hasFieldChanged("calculate_tax_on_tax") {
			setClauses = append(setClauses, "calculate_tax_on_tax = ?")
			values = append(values, t.Calculate_tax_on_tax)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "maximum_amount_qty = ?")
		values = append(values, t.Maximum_amount_qty)
		setClauses = append(setClauses, "tax_below_maximum = ?")
		values = append(values, t.Tax_below_maximum)
		setClauses = append(setClauses, "tax_above_maximum = ?")
		values = append(values, t.Tax_above_maximum)
		setClauses = append(setClauses, "calculate_tax_on_tax = ?")
		values = append(values, t.Calculate_tax_on_tax)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["tax_jurisdiction_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Tax_jurisdiction_code)
	}
	if old, ok := t.oldValues["tax_group_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Tax_group_code)
	}
	if old, ok := t.oldValues["tax_type"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Tax_type)
	}
	if old, ok := t.oldValues["effective_date"]; ok {
		values = append(values, types.KeyDate(old))
	} else {
		values = append(values, types.KeyDate(t.Effective_date))
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND tax_jurisdiction_code = ? AND tax_group_code = ? AND tax_type = ? AND effective_date = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Tax_Detail: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *TaxDetail) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "tax_jurisdiction_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Tax_jurisdiction_code.Equal(old)
		}
	case "tax_group_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Tax_group_code.Equal(old)
		}
	case "tax_type":
		if old, ok := oldValue.(TaxDetailTax_type); ok {
			return t.Tax_type != old
		}
	case "maximum_amount_qty":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Maximum_amount_qty.Equal(old)
		}
	case "tax_below_maximum":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Tax_below_maximum.Equal(old)
		}
	case "tax_above_maximum":
		if old, ok := oldValue.(types.Decimal); ok {
			return !t.Tax_above_maximum.Equal(old)
		}
	case "effective_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Effective_date.Equal(old)
		}
	case "calculate_tax_on_tax":
		if old, ok := oldValue.(bool); ok {
			return t.Calculate_tax_on_tax != old
		}
		return true // Type mismatch, assume changed
	}

	return false
}

